def endpoint(base_url, path):
    # Normalise the base by trimming any trailing slash so the version check
    # is reliable and the joined URL stays clean.
    base = base_url.rstrip('/')

    # If the base already carries the version suffix (for example a deployment
    # prefix ending in "/v1"), don't inject another "/v1". Note that this is a
    # strict match on the trailing "/v1", so a prefix like "/v10" is preserved
    # and a fresh "/v1" is still added before the resource.
    if base.endswith('/v1'):
        return base + '/' + path.lstrip('/')

    return base + '/v1/' + path.lstrip('/')

