def admit(active, waiting, budget, slots):
    # Any reservation larger than the entire budget can never be admitted,
    # even if FIFO processing would stop before reaching it.
    for value in waiting:
        if value > budget:
            raise ValueError("reservation exceeds total budget")

    admitted = []
    for value in waiting:
        if sum(active) + sum(admitted) + value > budget:
            break  # does not fit in the budget
        if len(active) + len(admitted) >= slots:
            break  # no slot left
        admitted.append(value)

    return admitted, waiting[len(admitted):]

