def endpoint(base_url, path):
    # Strip any trailing slashes so the base is normalized, e.g. "v1/" -> "v1".
    base = base_url.rstrip('/')

    # Preserve the deployment prefix and include exactly one /v1 segment.
    # If the base already ends with the "/v1" version segment, don't append
    # another one; otherwise insert "/v1" before the resource.
    if not base.endswith('/v1'):
        base += '/v1'

    return base + '/' + path.lstrip('/')

