def admit(active, waiting, budget, slots):
    # A reservation that by itself exceeds the total budget is invalid,
    # even if the FIFO scan would never reach it.
    for value in waiting:
        if value > budget:
            raise ValueError('reservation exceeds total budget')

    # FIFO: admit reservations while both the budget and the number of
    # available slots allow it, then stop at the first one that fits neither.
    admitted = []
    for value in waiting:
        fits_budget = sum(active) + sum(admitted) + value <= budget
        fits_slots = len(active) + len(admitted) < slots
        if fits_budget and fits_slots:
            admitted.append(value)
        else:
            break

    return admitted, waiting[len(admitted):]

